"""Imports Flask and its dependencies from /opt/py/flask.zip (9p).

Over 9p every file the guest opens is fetched again from the web server,
and `import flask` opens about 200 files.  scripts/make-flask-zip.py packs
them into one zip; this finder reads the zip once per process and imports
the modules from memory.  (zipimport would reopen the zip for every module,
fetching it again each time.)

The zip is not put on sys.path: every import not found elsewhere (site.py
tries sitecustomize at each start) would then fetch it, also for programs
that never use Flask.  The finder answers only for the packed packages.
Loaded at startup by lab-flask.pth.
"""

import sys

ZIP = "/opt/py/flask.zip"
PACKAGES = frozenset(
    ["flask", "werkzeug", "jinja2", "markupsafe", "click", "itsdangerous", "blinker", "dotenv"]
)
_PREFIX = ZIP + "/"


def _norm(name):
    return name.replace("-", "_").replace(".", "_").lower()


class LabFlaskFinder:
    _zip = None  # zipfile.ZipFile over the bytes, read once
    _names = None

    @classmethod
    def _archive(cls):
        if cls._zip is None:
            import io
            import zipfile

            with open(ZIP, "rb") as f:
                cls._zip = zipfile.ZipFile(io.BytesIO(f.read()))
            cls._names = set(cls._zip.namelist())
        return cls._zip

    @classmethod
    def _read(cls, member):
        return cls._archive().read(member)

    # ---- importlib finder
    @classmethod
    def find_spec(cls, fullname, path=None, target=None):
        if path is None:
            if fullname not in PACKAGES:
                return None
        elif not any(isinstance(p, str) and p.startswith(_PREFIX) for p in path):
            return None
        try:
            cls._archive()
        except OSError:
            return None
        from importlib.machinery import ModuleSpec

        base = fullname.replace(".", "/")
        if base + "/__init__.pyc" in cls._names:
            spec = ModuleSpec(fullname, _LOADER, origin=_PREFIX + base + "/__init__.py", is_package=True)
            spec.submodule_search_locations = [_PREFIX + base]
        elif base + ".pyc" in cls._names:
            spec = ModuleSpec(fullname, _LOADER, origin=_PREFIX + base + ".py")
        else:
            return None
        spec.has_location = True
        return spec

    @classmethod
    def invalidate_caches(cls):
        pass

    # ---- importlib.metadata: version("flask"), entry points ...
    @classmethod
    def find_distributions(cls, context=None):
        name = getattr(context, "name", None)
        want = _norm(name) if name else None
        try:
            names = cls._archive() and cls._names
        except OSError:
            return iter(())
        found = []
        for member in sorted(names):
            parts = member.split("/")
            if len(parts) == 2 and parts[0].endswith(".dist-info") and parts[1] == "METADATA":
                dist = parts[0][: -len(".dist-info")].rsplit("-", 1)[0]
                if want is None or _norm(dist) == want:
                    found.append(_distribution(parts[0]))
        return iter(found)


class _Loader:
    """Loads modules from the zip in memory (.pyc, with .py for tracebacks)."""

    @staticmethod
    def _member(fullname):
        base = fullname.replace(".", "/")
        if base + "/__init__.pyc" in LabFlaskFinder._names:
            return base + "/__init__"
        return base

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        exec(self.get_code(module.__name__), module.__dict__)

    def get_code(self, fullname):
        import marshal

        data = LabFlaskFinder._read(self._member(fullname) + ".pyc")
        return marshal.loads(memoryview(data)[16:])  # 16-byte pyc header

    def get_source(self, fullname):
        try:
            return LabFlaskFinder._read(self._member(fullname) + ".py").decode("utf-8")
        except KeyError:
            return None

    def is_package(self, fullname):
        return self._member(fullname).endswith("/__init__")

    def get_filename(self, fullname):
        return _PREFIX + self._member(fullname) + ".py"

    def get_data(self, path):
        # pkgutil.get_data and friends: a file inside the zip
        if path.startswith(_PREFIX):
            try:
                return LabFlaskFinder._read(path[len(_PREFIX):])
            except KeyError:
                pass
        raise OSError(path)


_LOADER = _Loader()


def _distribution(dist_info):
    import importlib.metadata
    import pathlib

    class _ZipDistribution(importlib.metadata.Distribution):
        def read_text(self, filename):
            try:
                return LabFlaskFinder._read(dist_info + "/" + filename).decode("utf-8")
            except KeyError:
                return None

        def locate_file(self, path):
            return pathlib.PurePosixPath(ZIP) / path

    return _ZipDistribution()


if not any(getattr(f, "__name__", "") == "LabFlaskFinder" for f in sys.meta_path):
    # First: otherwise the path finder's zipimport hook would load the
    # submodules (their __path__ is inside the zip), reopening the zip each time.
    sys.meta_path.insert(0, LabFlaskFinder)
